#!/usr/bin/env bash
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
OUT="$ROOT/meeting-service/patches/vexa-live-pcm-forward.ts"
mkdir -p "$(dirname "$OUT")"
base64 -d <<'B64' >"$OUT"

B64
if ! grep -q buildLivePcmJoinUrl "$OUT"; then
  echo "bootstrap failed" >&2
  exit 1
fi
VENDOR_DST="$ROOT/vendor/vexa/core/meetings/services/bot/src/live-pcm-forward.ts"
mkdir -p "$(dirname "$VENDOR_DST")"
cp "$OUT" "$VENDOR_DST"
echo "Wrote $OUT and $VENDOR_DST ($(wc -c <"$OUT") bytes)"
